		public static extern unsafe global::Windows.Win32.Foundation.NTSTATUS FwpmFilterAdd0(global::Windows.Win32.Foundation.HANDLE engineHandle, global::Windows.Win32.NetworkManagement.WindowsFilteringPlatform.FWPM_FILTER0* filter, [Optional] global::Windows.Win32.Security.PSECURITY_DESCRIPTOR sd, [Optional] ulong* id);

